    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    # Every non-background rectangular frame is a container: its interior is
    # uniformly replaced with 7 when it contains a non-frame seed/pattern.
    bg = max(set(x for row in grid for x in row), key=lambda x: sum(row.count(x) for row in grid))
    for r0 in range(h):
