                for c1 in range(c0 + 2, w):
                    color = grid[r0][c0]
                    if color == bg:
                        continue
                    if any(grid[r0][c] != color or grid[r1][c] != color for c in range(c0, c1 + 1)):
                        continue
                    if any(grid[r][c0] != color or grid[r][c1] != color for r in range(r0, r1 + 1)):
                        continue
                    inside = [grid[r][c] for r in range(r0 + 1, r1) for c in range(c0 + 1, c1)]
                    if inside and any(x != color for x in inside):
                        for r in range(r0 + 1, r1):
                            for c in range(c0 + 1, c1):
                                out[r][c] = 7
    return out

if __name__ == '__main__':
    import json, sys
    print(json.dumps(transform(json.load(sys.stdin))))
